Below is a ready-to-paste Arduino .ino matched to your PCB pin mapping and conservative TB6612FNG defaults. SKETCH_VERSION is included. Read the short flashing/test checklist after the code — I will not flash without your explicit confirmation.

Note: ENC_LEFT uses an interrupt (D2). ENC_RIGHT is on D4 (no external-int on many Nano/Uno boards), so ENC_RIGHT is polled — this matches your PCB wiring without requiring rewiring.

-------------------- begin sketch --------------------
/*
  UpRight.os - PCB matched balancer sketch (minimal, non-invasive)
  SKETCH_VERSION: pcb_v1.0
  Target: Arduino Nano style (AVR)
  Board wiring (matched to your PCB):
    PWMA   = D5
    PWMB   = D6
    AIN1   = D7
    AIN2   = not used (-1)  // if present on PCB, set here
    BIN1   = D12
    BIN2   = not used (-1)  // if present on PCB, set here
    STBY/GATE = D8
    ENC_LEFT  = D2  (uses external interrupt)
    ENC_RIGHT = D4  (polled; D4 used by PCB)
    I2C SDA/SCL = A4 / A5 (MPU6050)
  Motor driver: TB6612FNG
  Default safety limits:
    out_max_pct = 50 (%)
    i_max_ma = 1000 (1.0 A) // used only for integrator clamping heuristic
*/

#include <Wire.h>
#include <Arduino.h>

// SKETCH VERSION
#define SKETCH_VERSION "pcb_v1.0"

// Pin mapping (PCB)
const int PWMA_PIN = 5;    // D5
const int PWMB_PIN = 6;    // D6
const int AIN1_PIN = 7;    // D7
const int AIN2_PIN = -1;   // set to PCB pin if available
const int BIN1_PIN = 12;   // D12
const int BIN2_PIN = -1;   // set if available
const int STBY_PIN = 8;    // D8 (STBY/GATE)
const int ENC_L_PIN = 2;   // D2 (INT0)
const int ENC_R_PIN = 4;   // D4 (polled)
const int LED_PIN = 13;    // status

// IMU (MPU6050) I2C address and regs
const uint8_t MPU_ADDR = 0x68;
const uint8_t MPU_PWR_MGMT_1 = 0x6B;
const uint8_t MPU_ACCEL_XOUT_H = 0x3B;

// Control loop timing
const unsigned long LOOP_US = 5000UL; // 200 Hz

// PID defaults (match live context)
volatile float KP = 14.0;
volatile float KI = 0.0;
volatile float KD = 0.0;

// Motion / limits
volatile float OUT_MAX_PCT = 50.0; // % of full-scale PWM
volatile int I_MAX_MA = 1000;      // A*1000 for integrator clamp heuristic (not a current measure)

// Internal state
volatile long encL_count = 0;
volatile long encR_count = 0;
volatile int encR_last_state = 0;

float angle = 0.0;        // filtered angle (deg)
float rawAngle = 0.0;     // accel-derived angle (deg)
float gyroRate = 0.0;     // deg/s (from gyro)
float setpoint_deg = 0.0; // angle setpoint (deg)
float integrator = 0.0;
float prev_error = 0.0;
float alpha_cf = 0.98;    // complementary filter alpha

unsigned long last_loop_us = 0;
unsigned long last_imu_us = 0;

// MPU helper
void mpuWrite(uint8_t reg, uint8_t val) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(reg);
  Wire.write(val);
  Wire.endTransmission();
}

bool mpuReadRaw(int16_t* ax, int16_t* ay, int16_t* az, int16_t* gx, int16_t* gy, int16_t* gz) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(MPU_ACCEL_XOUT_H);
  if (Wire.endTransmission(false) != 0) return false;
  Wire.requestFrom(MPU_ADDR, (uint8_t)14);
  if (Wire.available() < 14) return false;
  *ax = (Wire.read() << 8) | Wire.read();
  *ay = (Wire.read() << 8) | Wire.read();
  *az = (Wire.read() << 8) | Wire.read();
  *gx = (Wire.read() << 8) | Wire.read();
  *gy = (Wire.read() << 8) | Wire.read();
  *gz = (Wire.read() << 8) | Wire.read();
  return true;
}

// Encoder ISRs / handlers
void IRAM_ATTR encL_ISR() {
  bool a = digitalRead(ENC_L_PIN);
  bool b = false; // if you have quadrature B, read it here
  // simple count on edge (single-channel)
  if (a) encL_count++;
  else encL_count--;
}

void pollEncR() {
  int s = digitalRead(ENC_R_PIN);
  if (s != encR_last_state) {
    // simple single-channel change counting
    if (s == HIGH) encR_count++;
    else encR_count--;
    encR_last_state = s;
  }
}

// Motor low-level
void motor_enable(bool enable) {
  digitalWrite(STBY_PIN, enable ? HIGH : LOW);
}

void motor_drive_single(int pwm_pin, int in1_pin, int in2_pin, float cmd_pct) {
  // cmd_pct: -100..+100 percent
  float out_pct = constrain(cmd_pct, -100.0, 100.0);
  int duty = (int)(abs(out_pct) / 100.0 * 255.0);
  if (in2_pin >= 0) {
    // canonical two-pin direction
    if (out_pct >= 0) {
      digitalWrite(in1_pin, HIGH);
      digitalWrite(in2_pin, LOW);
    } else {
      digitalWrite(in1_pin, LOW);
      digitalWrite(in2_pin, HIGH);
    }
  } else {
    // single-direction line style (driver PCB may implement direction differently)
    if (out_pct >= 0) digitalWrite(in1_pin, HIGH);
    else digitalWrite(in1_pin, LOW);
  }
  analogWrite(pwm_pin, duty);
}

void motor_drive(float left_pct, float right_pct) {
  motor_drive_single(PWMA_PIN, AIN1_PIN, AIN2_PIN, left_pct);
  motor_drive_single(PWMB_PIN, BIN1_PIN, BIN2_PIN, right_pct);
}

// Simple complementary filter + MPU6050 read
bool readIMU_and_update(float dt_s) {
  int16_t ax, ay, az, gx, gy, gz;
  if (!mpuReadRaw(&ax, &ay, &az, &gx, &gy, &gz)) return false;
  // accel angle (pitch) using X and Z: atan2(ax, az)
  float ax_g = (float)ax / 16384.0; // assuming ±2g (default)
  float az_g = (float)az / 16384.0;
  rawAngle = atan2(ax_g, az_g) * 180.0 / PI; // degrees
  // gyro Y axis (pitch rate) - raw sensitivity 131 LSB/(deg/s) for ±250 dps
  gyroRate = (float)gy / 131.0; // deg/s
  // Complementary filter
  float angle_from_gyro = angle + gyroRate * dt_s;
  angle = alpha_cf * angle_from_gyro + (1.0 - alpha_cf) * rawAngle;
  return true;
}

// PID (derivative on PV via gyroRate)
float pid_compute(float dt_s) {
  float error = setpoint_deg - angle;
  // P
  float p = KP * error;
  // I (trapezoidal)
  integrator += 0.5 * (error + prev_error) * dt_s * KI;
  // anti-windup: clamp integrator to reasonable value derived from I_MAX_MA and OUT_MAX_PCT
  // heuristics: translate i_max to percent using motor torque constant unknown; clamp integrator to prevent runaway
  float integrator_max = 100.0; // percent units - conservative clamp
  integrator = constrain(integrator, -integrator_max, integrator_max);
  float i = integrator;
  // D using gyro (d/dt of angle) -> derivative term = -KD * gyroRate
  float d = -KD * gyroRate;
  prev_error = error;
  float u = p + i + d;
  // clamp to output limits
  float out_max_pct = OUT_MAX_PCT;
  u = constrain(u, -out_max_pct, out_max_pct);
  return u; // percent -100..+100
}

// Serial command parsing (very small subset)
void processSerialLine(String &line) {
  line.trim();
  if (line.length() == 0) return;
  // simple tokenization
  char cmd[32];
  float a=0,b=0,c=0;
  int n = sscanf(line.c_str(), "%31s %f %f %f", cmd, &a, &b, &c);
  if (strcmp(cmd, "PID") == 0 && n >= 2) {
    noInterrupts();
    KP = a;
    if (n >= 3) KI = b;
    if (n >= 4) KD = c;
    interrupts();
    Serial.print("ACK PID ");
    Serial.print(KP); Serial.print(" "); Serial.print(KI); Serial.print(" "); Serial.println(KD);
  } else if (strcmp(cmd, "SETPOINT") == 0 && n >= 2) {
    setpoint_deg = a;
    Serial.print("ACK SETPOINT "); Serial.println(setpoint_deg);
  } else if (strcmp(cmd, "LIMITS") == 0 && n >= 3) {
    OUT_MAX_PCT = a;
    I_MAX_MA = (int)b;
    Serial.print("ACK LIMITS "); Serial.print(OUT_MAX_PCT); Serial.print(" "); Serial.println(I_MAX_MA);
  } else if (strcmp(cmd, "CAL_ZERO") == 0) {
    // record current angle as zero offset (not persistent)
    // (safety: user must confirm before using in production)
    Serial.println("ACK CAL_ZERO not implemented in minimal sketch - use on host");
  } else if (strcmp(cmd, "STATUS") == 0) {
    Serial.print("VER "); Serial.print(SKETCH_VERSION);
    Serial.print(" ANG "); Serial.print(angle);
    Serial.print(" RAW "); Serial.print(rawAngle);
    Serial.print(" GYRO "); Serial.print(gyroRate);
    Serial.print(" KP "); Serial.print(KP);
    Serial.print(" KI "); Serial.print(KI);
    Serial.print(" KD "); Serial.println(KD);
  } else {
    Serial.print("ERR Unknown cmd: "); Serial.println(cmd);
  }
}

String serialBuf;

void setup() {
  // pins
  pinMode(PWMA_PIN, OUTPUT);
  pinMode(PWMB_PIN, OUTPUT);
  if (AIN1_PIN >= 0) pinMode(AIN1_PIN, OUTPUT);
  if (AIN2_PIN >= 0) pinMode(AIN2_PIN, OUTPUT);
  if (BIN1_PIN >= 0) pinMode(BIN1_PIN, OUTPUT);
  if (BIN2_PIN >= 0) pinMode(BIN2_PIN, OUTPUT);
  pinMode(STBY_PIN, OUTPUT);
  pinMode(ENC_L_PIN, INPUT_PULLUP);
  pinMode(ENC_R_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);

  digitalWrite(PWMA_PIN, 0);
  digitalWrite(PWMB_PIN, 0);
  motor_enable(false); // keep motors disabled until operator explicit

  // encoder
  attachInterrupt(digitalPinToInterrupt(ENC_L_PIN), encL_ISR, CHANGE);
  encR_last_state = digitalRead(ENC_R_PIN);

  // I2C / MPU
  Wire.begin();
  mpuWrite(MPU_PWR_MGMT_1, 0x00); // wake up MPU6050
  delay(50);

  Serial.begin(115200);
  delay(50);
  Serial.print("UpRight.os minimal balancer ");
  Serial.println(SKETCH_VERSION);
  Serial.print("Pins: PWMA="); Serial.print(PWMA_PIN);
  Serial.print(" PWMB="); Serial.print(PWMB_PIN);
  Serial.print(" AIN1="); Serial.print(AIN1_PIN);
  Serial.print(" BIN1="); Serial.println(BIN1_PIN);
  last_loop_us = micros();
  last_imu_us = micros();
}

void loop() {
  unsigned long now_us = micros();
  unsigned long dt_us = now_us - last_loop_us;
  if (dt_us < LOOP_US) {
    // still time; but poll serial and encR
    if (Serial.available()) {
      char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (serialBuf.length() > 0) {
          processSerialLine(serialBuf);
          serialBuf = "";
        }
      } else serialBuf += c;
    }
    pollEncR();
    return;
  }
  // one control tick
  float dt_s = dt_us / 1e6;
  last_loop_us = now_us;

  // Read IMU and update angle
  bool imu_ok = readIMU_and_update(dt_s);
  if (!imu_ok) {
    // error reading IMU - indicate via LED blink pattern
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(LED_PIN, LOW);
  }

  // Poll encoder right (no ext-int)
  pollEncR();

  // Compute PID output percent (-100..100)
  float u_pct = pid_compute(dt_s);

  // Convert to left/right motor commands.
  // For simple 1D balance: both wheels same command (body forward/back)
  float left_cmd = u_pct;
  float right_cmd = u_pct;

  // Apply motor enable safety: motors are off until motor_enable(true) called
  // motor_enable(true) must be set by operator via a safe procedure (not auto)
  // To keep sketch conservative, we do not auto-enable motors even if controller runs.
  // If user wants to enable, send serial "ENABLE 1" or call motor_enable(true) in code.
  // (Left as explicit manual step)
  // Here we write outputs but they will be zero if STBY is LOW.
  motor_drive(left_cmd, right_cmd);

  // Emit periodic status over serial (lightweight)
  static unsigned long last_status_ms = 0;
  if (millis() - last_status_ms > 200) {
    last_status_ms = millis();
    Serial.print("STAT ");
    Serial.print("ANG "); Serial.print(angle, 3);
    Serial.print(" RAW "); Serial.print(rawAngle, 3);
    Serial.print(" GYRO "); Serial.print(gyroRate, 2);
    Serial.print(" OUT "); Serial.print(u_pct, 2);
    Serial.print(" ENC_L "); Serial.print(encL_count);
    Serial.print(" ENC_R "); Serial.println(encR_count);
  }

  // also keep reading serial commands
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') {
      if (serialBuf.length() > 0) {
        processSerialLine(serialBuf);
        serialBuf = "";
      }
    } else serialBuf += c;
  }
}
--------------------- end sketch ---------------------

Flashing / test checklist (short, follow exactly)
- 1) Review the code and confirm AIN2_PIN/BIN2_PIN values: if your PCB actually exposes those pins, set them; otherwise keep -1.
- 2) Compile in Arduino IDE / CLI for board: Arduino Nano (ATmega328). Fix board selection if necessary.
- 3) Safety before connect: remove wheels or lift robot off ground OR disconnect motor power supply. Keep the TB6612 STBY line controlled by sketch (it starts LOW).
- 4) Upload the sketch. Do NOT enable motors yet.
- 5) With serial monitor 115200, send "STATUS" to verify IMU angle updates and encoder counters (ENC_L/ENC_R changing when you move shafts).
- 6) If IMU and encoders look sensible, enable motors with a controlled step:
    - Manually set STBY HIGH from serial command (I can add a small serial "ENABLE 1" handler if you want) or temporarily set motor_enable(true) in code and re-flash.
    - First test at low OUT_MAX_PCT (e.g., 10%). Verify motor direction and encoder increments.
    - Step OUT_MAX_PCT upward gradually (20% -> 50%) only if behaviour is stable.

If you'd like, I can:
- Add a simple serial "ENABLE 1" / "ENABLE 0" command to toggle STBY, or
- Replace the ENC_RIGHT polling with a PCINT-based ISR (if you prefer interrupt-driven encoders),
- Or produce a compile-ready upload package and (after you confirm) include the exact UPRIGHT_APPLY_JSON patch to set runtime defaults (kp/ki/kd/out_max/i_max).

Which of those (ENABLE command / PCINT encoder ISR / apply runtime defaults) do you want next?

