Below is the full .ino to paste into the Arduino IDE (matches your PCB pins and TB6612FNG driver). It:
- Uses ENC_LEFT = D2 and ENC_RIGHT = D4 (PCINT-based counting for both),
- Motor DIRs: LEFT_DIR = D7, RIGHT_DIR = D12; PWMs: D5/D6; STBY/GATE = D8,
- Basic MPU6050 complementary-filter angle (if MPU6050 present on A4/A5),
- Serial commands: STATUS, ENABLE 1/0, PWM <L> <R>, MTEST,
- Safety: motors stay in STBY until you explicitly ENABLE 1; no auto-arm.

Paste everything between the lines into an .ino file and compile for Arduino Nano.

--- begin pcb_pinned_test.ino ---
/*
  pcb_pinned_test.ino
  PCB pin mapping test for TB6612FNG-based robot
  - ENC_LEFT: D2 (PD2)
  - ENC_RIGHT: D4 (PD4)
  - LEFT_DIR: D7
  - RIGHT_DIR: D12
  - PWMA: D5 (left PWM)
  - PWMB: D6 (right PWM)
  - STBY/GATE: D8
  - I2C: A4(SDA), A5(SCL) for MPU6050 (optional)
  Serial commands:
    STATUS           -> prints telemetry
    ENABLE 1         -> set STBY HIGH (motors allowed)
    ENABLE 0         -> set STBY LOW (motors disabled)
    PWM <L> <R>      -> set signed PWM -127..127 (respects OUT_MAX)
    MTEST            -> short safe motor test pulse (requires ENABLE 1)
*/

#include <Wire.h>
#include <Arduino.h>

// ---------- PCB pin mapping ----------
const uint8_t ENC_LEFT_PIN = 2;   // PD2 (also PCINT)
const uint8_t ENC_RIGHT_PIN = 4;  // PD4 (PCINT)
const uint8_t LEFT_DIR_PIN = 7;
const uint8_t RIGHT_DIR_PIN = 12;
const uint8_t PWMA_PIN = 5;
const uint8_t PWMB_PIN = 6;
const uint8_t STBY_PIN = 8;

// MPU6050 registers
const uint8_t MPU_ADDR = 0x68;
const uint8_t PWR_MGMT_1 = 0x6B;
const uint8_t ACCEL_XOUT_H = 0x3B;
const uint8_t GYRO_YOUT_H = 0x45;

// Control defaults
volatile long encLeft = 0;
volatile long encRight = 0;
volatile uint8_t portd_prev = 0;

int out_max_pct = 50;      // percent (0-100); from UPRIGHT_APPLY_JSON
float i_max_amp = 1.0;     // A, for operator info only

// Complementary filter state
float angle = 0.0;         // degrees
unsigned long lastMicros = 0;
const float alpha = 0.98;  // gyro weight
float raw_acc_angle = 0.0;
float gyro_dps = 0.0;

// Helper: limit PWM by out_max_pct
int applyOutLimit(int v_signed) {
  int sign = (v_signed >= 0) ? 1 : -1;
  int mag = abs(v_signed);
  int max255 = map(out_max_pct, 0, 100, 0, 255);
  if (mag > max255) mag = max255;
  return sign * mag;
}

// Motor control (single DIR pin assumed per motor on this PCB)
void setMotorLeft(int val) {
  // val in -255..255
  int v = applyOutLimit(constrain(val, -255, 255));
  if (v >= 0) digitalWrite(LEFT_DIR_PIN, HIGH);
  else digitalWrite(LEFT_DIR_PIN, LOW);
  analogWrite(PWMA_PIN, abs(v));
}
void setMotorRight(int val) {
  int v = applyOutLimit(constrain(val, -255, 255));
  if (v >= 0) digitalWrite(RIGHT_DIR_PIN, HIGH);
  else digitalWrite(RIGHT_DIR_PIN, LOW);
  analogWrite(PWMB_PIN, abs(v));
}

// ---------- PCINT for PD0..PD7 (will capture D2 and D4) ----------
ISR(PCINT2_vect) {
  uint8_t portd_now = PIND;
  uint8_t changed = portd_now ^ portd_prev;
  if (changed & (1 << 2)) { // D2 changed -> ENC_LEFT_PIN
    // count rising edges only
    if (portd_now & (1 << 2)) encLeft++;
  }
  if (changed & (1 << 4)) { // D4 changed -> ENC_RIGHT_PIN
    if (portd_now & (1 << 4)) encRight++;
  }
  portd_prev = portd_now;
}

// ---------- MPU6050 simple read ----------
void mpuInit() {
  Wire.begin();
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(PWR_MGMT_1);
  Wire.write(0x00); // wake
  Wire.endTransmission();
  delay(50);
}
int16_t read16(uint8_t addr) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(addr);
  Wire.endTransmission(false);
  Wire.requestFrom(MPU_ADDR, (uint8_t)2);
  while (Wire.available() < 2) ;
  int16_t v = (Wire.read() << 8) | Wire.read();
  return v;
}
void updateIMU() {
  // simple complementary filter for pitch (using accel X,Z and gyro Y)
  unsigned long now = micros();
  float dt = (lastMicros == 0) ? 0.01f : (now - lastMicros) / 1e6f;
  lastMicros = now;
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(ACCEL_XOUT_H);
  Wire.endTransmission(false);
  Wire.requestFrom(MPU_ADDR, (uint8_t)6);
  if (Wire.available() < 6) return;
  int16_t ax = (Wire.read() << 8) | Wire.read();
  int16_t ay = (Wire.read() << 8) | Wire.read(); // not used
  int16_t az = (Wire.read() << 8) | Wire.read();
  // gyro Y
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(GYRO_YOUT_H);
  Wire.endTransmission(false);
  Wire.requestFrom(MPU_ADDR, (uint8_t)2);
  if (Wire.available() < 2) return;
  int16_t gy = (Wire.read() << 8) | Wire.read();

  // scales: accel ~16384 LSB/g, gyro ~131 LSB/(°/s) (default ranges)
  float axg = (float)ax / 16384.0f;
  float azg = (float)az / 16384.0f;
  raw_acc_angle = atan2f(axg, azg) * 180.0f / PI;  // degrees
  gyro_dps = (float)gy / 131.0f; // deg/s

  // complementary filter
  angle = alpha * (angle + gyro_dps * dt) + (1.0f - alpha) * raw_acc_angle;
}

// ---------- Serial command parser ----------
String inputLine = "";
void handleLine(String s) {
  s.trim();
  if (s.length() == 0) return;
  if (s.equalsIgnoreCase("STATUS")) {
    // print a compact CSV-like status line
    noInterrupts();
    long l = encLeft;
    long r = encRight;
    interrupts();
    updateIMU();
    Serial.print("STATUS,ang,"); Serial.print(angle, 3);
    Serial.print(",raw,"); Serial.print(raw_acc_angle, 3);
    Serial.print(",gyro,"); Serial.print(gyro_dps, 3);
    Serial.print(",encL,"); Serial.print(l);
    Serial.print(",encR,"); Serial.print(r);
    Serial.print(",out_max_pct,"); Serial.print(out_max_pct);
    Serial.print(",i_max_A,"); Serial.print(i_max_amp, 2);
    Serial.println();
    return;
  }
  if (s.startsWith("ENABLE")) {
    int val = s.substring(6).toInt();
    if (val) {
      digitalWrite(STBY_PIN, HIGH);
      Serial.println("OK:STBY=1");
    } else {
      digitalWrite(STBY_PIN, LOW);
      // also stop motors for safety
      setMotorLeft(0); setMotorRight(0);
      Serial.println("OK:STBY=0");
    }
    return;
  }
  if (s.startsWith("PWM")) {
    // PWM <L> <R> where values are -127..127 (we scale to 255 range)
    int spL = 0, spR = 0;
    int sep = s.indexOf(' ');
    if (sep > 0) {
      String rest = s.substring(sep+1);
      int sep2 = rest.indexOf(' ');
      if (sep2 > 0) {
        spL = rest.substring(0, sep2).toInt();
        spR = rest.substring(sep2+1).toInt();
      } else {
        spL = rest.toInt();
      }
    }
    // scale from -127..127 to -255..255
    int vL = constrain(spL, -127, 127) * 2;
    int vR = constrain(spR, -127, 127) * 2;
    setMotorLeft(vL);
    setMotorRight(vR);
    Serial.print("OK:PWM L="); Serial.print(vL); Serial.print(" R="); Serial.println(vR);
    return;
  }
  if (s.equalsIgnoreCase("MTEST")) {
    Serial.println("MTEST: verifying short low-power pulses");
    // require STBY high
    if (digitalRead(STBY_PIN) == LOW) {
      Serial.println("ERR: STBY LOW - ENABLE 1 first");
      return;
    }
    // short safe pulses
    setMotorLeft(80);
    setMotorRight(-80);
    delay(300);
    setMotorLeft(0);
    setMotorRight(0);
    Serial.println("MTEST:done");
    return;
  }
  if (s.startsWith("OUTMAX")) {
    // OUTMAX <pct>
    int pct = s.substring(6).toInt();
    pct = constrain(pct, 0, 100);
    out_max_pct = pct;
    Serial.print("OK:OUT_MAX="); Serial.println(out_max_pct);
    return;
  }
  Serial.print("ERR:unknown_cmd:"); Serial.println(s);
}

// ---------- setup ----------
void setupPinsAndPCINT() {
  pinMode(ENC_LEFT_PIN, INPUT_PULLUP);
  pinMode(ENC_RIGHT_PIN, INPUT_PULLUP);
  // set up PCINT for D0..D7 (PCINT2)
  portd_prev = PIND;
